{
  "title": "Creamy Chickpea & Broccoli Rice Bowls",
  "description": "A hearty, dairy-free rice bowl with a savory peanut sauce and roasted broccoli. Safe for peanut and sesame allergies.",
  "source_name": "AI Recipe Idea",
  "story": "This recipe transforms pantry staples into a comforting meal. The peanut butter creates a rich, creamy sauce without dairy, while the broccoli adds a fresh crunch. Perfect for a quick, allergy-friendly dinner.",
  "prep_minutes": 15,
  "cook_minutes": 20,
  "servings": 4,
  "category": "Dinner",
  "tags": [
    "Peanut-Free",
    "Sesame-Free",
    "Vegetarian",
    "Gluten-Free"
  ],
  "ingredients": [
    {
      "quantity": "2",
      "unit": "cups",
      "item": "Uncooked white rice",
      "note": ""
    },
    {
      "quantity": "1",
      "unit": "can",
      "item": "Chickpeas, drained and rinsed",
      "note": ""
    },
    {
      "quantity": "1",
      "unit": "head",
      "item": "Broccoli, cut into florets",
      "note": ""
    },
    {
      "quantity": "1/2",
      "unit": "cup",
      "item": "Peanut butter",
      "note": ""
    },
    {
      "quantity": "2",
      "unit": "tbsp",
      "item": "Water",
      "note": ""
    },
    {
      "quantity": "1",
      "unit": "tbsp",
      "item": "Lemon juice",
      "note": ""
    },
    {
      "quantity": "1",
      "unit": "tsp",
      "item": "Garlic powder",
      "note": ""
    },
    {
      "quantity": "1",
      "unit": "tsp",
      "item": "Salt",
      "note": ""
    }
  ],
  "instructions": [
    {
      "body": "Cook rice according to package directions. Set aside."
    },
    {
      "body": "In a small bowl, whisk together peanut butter, water, lemon juice, garlic powder, and salt until smooth."
    },
    {
      "body": "Heat a large skillet over medium heat. Add broccoli and a splash of water. Cover and steam for 5 minutes until tender-crisp."
    },
    {
      "body": "Add chickpeas to the skillet. Cook for 3-4 minutes, stirring occasionally, until heated through."
    },
    {
      "body": "Divide cooked rice among four bowls. Top with broccoli and chickpeas."
    },
    {
      "body": "Drizzle the peanut sauce evenly over the bowls and serve immediately."
    }
  ]
}
